/* ── ROUTER ── */
const appEl=document.getElementById('app');
function go(page){
  curPage=page;
  if(communityUnsub){ communityUnsub(); communityUnsub=null; }
  communityUnsubAllReplies();
  adminUnsubAll(); // (added) tear down any live admin-panel listeners when leaving the page
  // Visiting a tool's own page again counts as "checking on it" — clear its
  // pill-hidden flag so the pill reappears the next time you navigate away.
  if(page==='stopwatch') swPillHidden=false;
  if(page==='countdown') cdPillHidden=false;
  // Clear ALL app timers to prevent background leaks
  clearInterval(ageTimer);
  clearTimeout(dayFinderTimer);
  clearInterval(snakeLoop);
  clearInterval(memTimer);
  clearInterval(sudokuInterval); sudokuInterval=null;
  clearInterval(wsInterval); wsInterval=null;
  clearInterval(typingTimer); typingStarted=false; typingDone=false;
  stopLifeStatsLive();
  // NOTE: stopwatch & countdown timer are intentionally NOT reset here —
  // they keep counting in the background (via timestamps) while you're
  // on another page, and the floating pill shows their live progress.
  clearInterval(swInterval);
  clearInterval(cdInterval);
  // Health timers
  clearInterval(breathInterval); breathInterval=null;
  clearInterval(lungTimer); lungTimer=null; lungRunning=false; lungPaused=false;
  clearInterval(brTimer); brTimer=null; brRunning=false; brPaused=false;
  clearInterval(stressTimer); stressTimer=null; stressRunning=false;
  clearInterval(eyeTimer); eyeTimer=null; eyeRunning=false;
  document.onkeydown=null;
  window.onmouseup=null;
  appEl.innerHTML='';
  if(isPageBlocked(page)){
    renderFeatureDisabledPage(page);
    injectHelpButton(page);
    if(seriousMode)stripEmojiInNode(appEl);
    window.scrollTo({top:0,behavior:'smooth'});
    applyFeatureFlagUI();
    return;
  }
  if(page==='home') renderHome();
  else if(page==='apps') renderAppList();
  else if(page==='games') renderGames();
  else if(page==='ttt') renderTTT();
  else if(page==='g2048') renderG2048();
  else if(page==='memory') renderMemory();
  else if(page==='snake') renderSnake();
  else if(page==='sudoku') renderSudoku();
  else if(page==='wordsearch') renderWordSearch();
  else if(page==='health') renderHealth();
  else if(page==='fun') renderFun();
  else if(page==='lifestats') renderLifeStats();
  else if(page==='science') renderScience();
  else if(page==='services') renderServices();
  else if(page==='community') renderCommunity();
  else if(page==='breath') renderBreath();
  else if(page==='lunghold') renderLungHold();
  else if(page==='breathrate') renderBreathRate();
  else if(page==='heartrate') renderHeartRate();
  else if(page==='heartzone') renderHeartZone();
  else if(page==='stress') renderStress();
  else if(page==='eyetimer') renderEyeTimer();
  else if(page==='water') renderWater();
  else if(page==='cycle') renderCycleTracker();
  else if(page==='planetweight') renderPlanetWeight();
  else if(page==='agemars') renderAgeMars();
  else if(page==='moonphase') renderMoonPhase();
  else if(page==='whatif') renderWhatIf();
  else if(page==='stopwatch') renderStopwatch();
  else if(page==='countdown') renderCountdown();
  else if(page==='about') renderAbout();
  else if(page==='auth') renderAuth();
  else if(page==='admin') renderAdmin();
  else if(page==='inbox') renderUserInbox();
  else{const a=APPS.find(x=>x.id===page);if(a)a.render();else renderHome();}
  injectHelpButton(page);
  if(seriousMode)stripEmojiInNode(appEl);
  window.scrollTo({top:0,behavior:'smooth'});
  if(page!=='auth') schedulePrefsSave(); /* remember the active section across reloads/devices (added) */
  applyFeatureFlagUI(); /* dim any paused tiles now visible on this page (added) */
}

