function initialsOf(user){
  if(!user)return '?';
  var n=user.displayName||user.email||'?';
  var parts=n.trim().split(/\s+/);
  if(parts.length>1) return (parts[0][0]+parts[1][0]).toUpperCase();
  return n[0].toUpperCase();
}

