function updateNavAuthUI(){
  var d=document.getElementById('navAuthSlotDesktop');
  var m=document.getElementById('navAuthSlotMobile');
  var mobileLabel=document.getElementById('navMobileAccountLabel');
  var html;
  if(currentUser){
    var pic=currentUser.photoDataUrl;
    var icons='';
    // Inbox bell (added) — visible to any signed-in user, badges the unread count.
    icons+='<button class="nav-icon-btn" onclick="go(\'inbox\')" title="Messages" aria-label="Messages">📥'
      +(userUnreadCount>0?'<span class="nav-icon-badge">'+(userUnreadCount>9?'9+':userUnreadCount)+'</span>':'')
      +'</button>';
    // Admin shield (added) — UX-only convenience link; real access control is enforced by
    // Firestore rules (isAdmin()) on every read/write, not by whether this button is shown.
    if(communityIsAdmin()){
      icons+='<button class="nav-icon-btn" onclick="go(\'admin\')" title="Admin dashboard" aria-label="Admin dashboard">🛡️</button>';
    }
    html='<span class="nav-icon-cluster">'+icons+'</span>'
      +'<button class="nav-avatar-btn" onclick="ksNavAccountClick()" title="Account">'
      +(pic?'<img src="'+pic+'" alt="Profile">':initialsOf(currentUser))
      +'</button>';
    if(mobileLabel) mobileLabel.textContent=currentUser.displayName||currentUser.email||'Account';
  }else{
    html='<button class="nav-auth-btn" onclick="go(\'auth\')">Sign In</button>';
    if(mobileLabel) mobileLabel.textContent='Sign In / Account';
  }
  if(d) d.innerHTML=html;
  if(m) m.innerHTML=html;
}

/* Called by the Firebase module script whenever auth state changes */
function onKsAuthStateChanged(user){
  var justSignedIn = !currentUser && user;
  currentUser=user;
  authReady=true;
  authBusy=false;
  startLiveFeatureFlags(); // (added) begin listening for admin pauses as soon as Firebase is ready
  startLiveAboutPhoto(); // (added) begin listening for the admin's About Me photo as soon as Firebase is ready
  if(user){ startUserInboxListener(); } else { stopUserInboxListener(); } // (added)
  updateNavAuthUI();
  var navigated=false;
  if(justSignedIn){
    /* Pull this account's saved appearance/settings/last-section from the cloud (e.g. on a new device);
       if the account has none yet, push what's currently active (from localStorage/defaults)
       up so it's backed up going forward. (added) */
    if(user.prefs){
      applyPrefs(user.prefs);
      savePrefsLocal();
      if(user.prefs.lastPage && user.prefs.lastPage!==curPage){ go(user.prefs.lastPage); navigated=true; }
      renderSettingsPanel();
    }else if(window.KSFirebase && window.KSFirebase.savePrefs){
      window.KSFirebase.savePrefs(collectPrefs()).catch(function(){});
    }
  }
  if(!navigated && curPage==='auth' && user){ go('home'); navigated=true; }
  if(document.getElementById('settingsDrawer') && document.getElementById('settingsDrawer').classList.contains('open')){
    if(settingsView==='menu' || settingsView==='account') renderSettingsPanel();
  }
  if(curPage==='auth') renderAuth();
  if(!navigated && curPage==='community') renderCommunity(); // refresh composer visibility after sign-in/out (added)
}

function ksFriendlyAuthError(err){
  var code=(err&&err.code)||'';
  var map={
    'auth/invalid-email':'That email address doesn\'t look right.',
    'auth/user-disabled':'This account has been disabled.',
    'auth/user-not-found':'No account found with that email. Try signing up instead.',
    'auth/wrong-password':'Incorrect password. Please try again.',
    'auth/invalid-credential':'Incorrect email or password.',
    'auth/email-already-in-use':'An account already exists with that email. Try signing in instead.',
    'auth/weak-password':'Please choose a password with at least 6 characters.',
    'auth/too-many-requests':'Too many attempts. Please wait a moment and try again.',
    'auth/popup-closed-by-user':'Google sign-in was closed before finishing.',
    'auth/network-request-failed':'Network error — please check your connection and try again.',
    'permission-denied':'Your account was created, but saving your profile was blocked by the database\'s security rules. This needs a one-time fix in the Firebase Console (Firestore → Rules).'
  };
  return map[code] || (err&&err.message ? err.message.replace('Firebase: ','').replace(/\s*\(auth\/[^)]+\)\.?/,'') : 'Something went wrong. Please try again.');
}

function ksSetAuthMode(mode){
  authMode=mode; authMsg=null; renderAuth();
}

function ksGoogleSignInClick(){
  if(!window.KSFirebase){ authMsg={type:'error',text:'Still connecting — please try again in a moment.'}; renderAuth(); return; }
  authBusy=true; authMsg=null; renderAuth();
  window.KSFirebase.googleSignIn().then(function(){
    authBusy=false;
  }).catch(function(err){
    authBusy=false;
    authMsg={type:'error',text:ksFriendlyAuthError(err)};
    renderAuth();
  });
}

function ksEmailFormSubmit(e){
  if(e&&e.preventDefault)e.preventDefault();
  if(!window.KSFirebase){ authMsg={type:'error',text:'Still connecting — please try again in a moment.'}; renderAuth(); return false; }
  var email=(document.getElementById('authEmail')||{}).value||'';
  var pw=(document.getElementById('authPassword')||{}).value||'';
  email=email.trim();
  authMsg=null;
  if(!email || !pw){ authMsg={type:'error',text:'Please fill in both fields.'}; renderAuth(); return false; }
  authBusy=true; renderAuth();
  if(authMode==='signup'){
    var name=((document.getElementById('authName')||{}).value||'').trim();
    if(pw.length<6){ authBusy=false; authMsg={type:'error',text:'Please choose a password with at least 6 characters.'}; renderAuth(); return false; }
    window.KSFirebase.emailSignUp(email,pw,name).then(function(){
      authBusy=false;
    }).catch(function(err){
      authBusy=false; authMsg={type:'error',text:ksFriendlyAuthError(err)}; renderAuth();
    });
  }else{
    window.KSFirebase.emailSignIn(email,pw).then(function(){
      authBusy=false;
    }).catch(function(err){
      authBusy=false; authMsg={type:'error',text:ksFriendlyAuthError(err)}; renderAuth();
    });
  }
  return false;
}

function ksForgotPassword(){
  var email=((document.getElementById('authEmail')||{}).value||'').trim();
  if(!email){ authMsg={type:'error',text:'Enter your email above first, then tap "Forgot password?" again.'}; renderAuth(); return; }
  if(!window.KSFirebase){ authMsg={type:'error',text:'Still connecting — please try again in a moment.'}; renderAuth(); return; }
  window.KSFirebase.sendReset(email).then(function(){
    authMsg={type:'success',text:'Password reset email sent to '+email+'. Check your inbox.'};
    renderAuth();
  }).catch(function(err){
    authMsg={type:'error',text:ksFriendlyAuthError(err)};
    renderAuth();
  });
}

