/* Resizes/compresses an image file client-side into a small square JPEG data URL
   (profile pictures are saved directly in Firestore, so they need to stay small —
   well under Firestore's 1MB-per-document limit). */
function ksCompressImageToDataUrl(file,maxSize,quality){
  return new Promise(function(resolve,reject){
    var img=new Image();
    var reader=new FileReader();
    reader.onerror=function(){reject(new Error('Could not read that file.'));};
    reader.onload=function(e){
      img.onerror=function(){reject(new Error('Could not read that image.'));};
      img.onload=function(){
        var side=Math.min(img.width,img.height);
        var sx=(img.width-side)/2, sy=(img.height-side)/2;
        var canvas=document.createElement('canvas');
        canvas.width=maxSize; canvas.height=maxSize;
        var ctx=canvas.getContext('2d');
        ctx.drawImage(img,sx,sy,side,side,0,0,maxSize,maxSize);
        resolve(canvas.toDataURL('image/jpeg',quality));
      };
      img.src=e.target.result;
    };
    reader.readAsDataURL(file);
  });
}

function ksProfilePicSelected(input){
  var file=input.files&&input.files[0];
  if(!file)return;
  if(!window.KSFirebase){ authMsg={type:'error',text:'Still connecting — please try again in a moment.'}; renderSettingsPanel(); return; }
  if(!file.type||file.type.indexOf('image/')!==0){ authMsg={type:'error',text:'Please choose an image file.'}; renderSettingsPanel(); return; }
  if(file.size>15*1024*1024){ authMsg={type:'error',text:'Please choose an image under 15MB.'}; renderSettingsPanel(); return; }
  authBusy=true; authMsg=null; renderSettingsPanel();
  ksCompressImageToDataUrl(file,200,0.72).then(function(dataUrl){
    var preview=document.getElementById('accountAvatarPreview');
    if(preview) preview.innerHTML='<img src="'+dataUrl+'" alt="Profile picture">';
    return window.KSFirebase.saveProfilePic(dataUrl);
  }).then(function(){
    authBusy=false; authMsg={type:'success',text:'Profile picture updated.'};
    renderSettingsPanel(); updateNavAuthUI();
  }).catch(function(err){
    authBusy=false; authMsg={type:'error',text:ksFriendlyAuthError(err)};
    renderSettingsPanel();
  });
}

// Lets the site admin replace the "About Me" photo on the home page without touching
// any code. Only visible to admins (communityIsAdmin()), and the write is enforced
// server-side by Firestore rules (isAdmin() on siteConfig/about) either way. (added)
function aboutPhotoSelected(input){
  var file=input.files&&input.files[0];
  if(!file)return;
  if(!window.KSFirebase||!window.KSFirebase.saveAboutPhoto){ alert('Still connecting — please try again in a moment.'); return; }
  if(!file.type||file.type.indexOf('image/')!==0){ alert('Please choose an image file.'); return; }
  if(file.size>15*1024*1024){ alert('Please choose an image under 15MB.'); return; }
  ksCompressImageToDataUrl(file,500,0.78).then(function(dataUrl){
    liveAboutPhoto=dataUrl; renderHome(); // reflect it instantly while the save goes through
    return window.KSFirebase.saveAboutPhoto(dataUrl);
  }).catch(function(err){
    alert('Could not update the photo: '+(err&&err.message?err.message:'please try again.'));
  });
}

function ksSaveDisplayNameClick(){
  var input=document.getElementById('accountNameInput');
  if(!input)return;
  var name=input.value.trim().slice(0,40);
  if(!name){ authMsg={type:'error',text:'Please enter a name (or nickname) first.'}; renderSettingsPanel(); return; }
  if(!window.KSFirebase||!window.KSFirebase.updateDisplayName){ authMsg={type:'error',text:'Still connecting — please try again in a moment.'}; renderSettingsPanel(); return; }
  authBusy=true; authMsg=null; renderSettingsPanel();
  window.KSFirebase.updateDisplayName(name).then(function(){
    authBusy=false; authMsg={type:'success',text:'Name updated.'};
    renderSettingsPanel(); updateNavAuthUI();
  }).catch(function(err){
    authBusy=false; authMsg={type:'error',text:ksFriendlyAuthError(err)};
    renderSettingsPanel();
  });
}

function ksSignOutClick(){
  var ok=confirm('Are you sure you want to log out?');
  if(!ok)return;
  if(!window.KSFirebase)return;
  authBusy=true; renderSettingsPanel();
  window.KSFirebase.doSignOut().then(function(){
    authBusy=false; closeSettings(); go('home');
  }).catch(function(err){
    authBusy=false; authMsg={type:'error',text:ksFriendlyAuthError(err)}; renderSettingsPanel();
  });
}

function ksDeleteAccountClick(){
  var ok=confirm('Are you absolutely sure? This will permanently delete your account and profile picture. This cannot be undone.');
  if(!ok)return;
  if(!window.KSFirebase)return;
  authBusy=true; authMsg=null; renderSettingsPanel();
  window.KSFirebase.deleteAccount().then(function(){
    authBusy=false; closeSettings(); go('home');
  }).catch(function(err){
    authBusy=false;
    if(err&&err.code==='auth/requires-recent-login'){
      authMsg={type:'error',text:'For your security, please log out and sign back in, then try deleting your account again right away.'};
    }else{
      authMsg={type:'error',text:ksFriendlyAuthError(err)};
    }
    renderSettingsPanel();
  });
}

