/* ═══════════════════════ FEATURE FLAG CATALOG (added) ═══════════════════════
   Every entry here maps a real page in the app to a Firestore flag key.
   Semantics: a key is "enabled" unless it's explicitly stored as false —
   so a brand-new install with an empty appConfig/features doc has
   everything on, and admins only ever need to flip OFF what they want
   to pause. Toggling one of these actually blocks that page for regular
   visitors (see isPageBlocked / go()) — it isn't just a label. */
const FEATURE_CATALOG=[
  {group:'Sections', items:[
    {key:'sec_games',      label:'Games section',        page:'games'},
    {key:'sec_health',     label:'Health Hub section',   page:'health'},
    {key:'sec_fun',        label:'Fun section',          page:'fun'},
    {key:'sec_science',    label:'Science section',      page:'science'},
    {key:'sec_services',   label:'Services section',     page:'services'},
    {key:'sec_community',  label:'Community',            page:'community'},
    {key:'sec_inbox',      label:'Inbox',                page:'inbox'},
    {key:'sec_lifestats',  label:'Life Stats',           page:'lifestats'},
    {key:'sec_apps',       label:'All Apps listing',     page:'apps'}
  ]},
  {group:'Games', items:[
    {key:'game_ttt',        label:'Tic Tac Toe',    page:'ttt'},
    {key:'game_2048',       label:'2048',            page:'g2048'},
    {key:'game_memory',     label:'Memory Match',    page:'memory'},
    {key:'game_snake',      label:'Snake',           page:'snake'},
    {key:'game_sudoku',     label:'Sudoku',          page:'sudoku'},
    {key:'game_wordsearch', label:'Word Search',     page:'wordsearch'}
  ]},
  {group:'Health tools', items:[
    {key:'health_breath',     label:'Breathing Exercise',   page:'breath'},
    {key:'health_lunghold',   label:'Lung Hold Timer',      page:'lunghold'},
    {key:'health_breathrate', label:'Breath Rate',          page:'breathrate'},
    {key:'health_heartrate',  label:'Heart Rate',           page:'heartrate'},
    {key:'health_heartzone',  label:'Heart Rate Zones',     page:'heartzone'},
    {key:'health_stress',     label:'Stress Check',         page:'stress'},
    {key:'health_eyetimer',   label:'Eye Care Timer',       page:'eyetimer'},
    {key:'health_water',      label:'Water Tracker',        page:'water'},
    {key:'health_cycle',      label:'Cycle Tracker',        page:'cycle'}
  ]},
  {group:'Fun & Science', items:[
    {key:'fun_planetweight', label:'Weight on Other Planets', page:'planetweight'},
    {key:'fun_agemars',      label:'Your Age on Mars',        page:'agemars'},
    {key:'fun_moonphase',    label:'Moon Phase',              page:'moonphase'},
    {key:'fun_whatif',       label:'What If Calculator',      page:'whatif'}
  ]},
  {group:'Utilities', items:[
    {key:'app_age',       label:'Age Calculator',            page:'age'},
    {key:'app_lcmhcf',    label:'LCM & HCF Calculator',      page:'lcmhcf'},
    {key:'app_bmi',       label:'BMI Calculator',            page:'bmi'},
    {key:'app_typing',    label:'Typing Speed Test',         page:'typing'},
    {key:'app_dayf',      label:'What Day Was It?',          page:'dayf'},
    {key:'app_passck',    label:'Password Strength Checker', page:'passck'},
    {key:'app_baseconv',  label:'Number Base Converter',     page:'baseconv'},
    {key:'app_wordcount', label:'Word & Character Counter',  page:'wordcount'},
    {key:'app_emi',       label:'EMI / Loan Calculator',     page:'emi'},
    {key:'app_unitconv',  label:'Unit Converter',            page:'unitconv'},
    {key:'app_timer',     label:'Stopwatch & Timer',         page:'timer'},
    {key:'app_decision',  label:'Random Decision Maker',     page:'decision'},
    {key:'app_calchub',   label:'Calculator Hub',            page:'calchub'},
    {key:'app_numwords',  label:'Number to Words',           page:'numwords'},
    {key:'app_morse',     label:'Morse Code Converter',      page:'morse'}
  ]}
];
var FEATURE_PAGE_MAP={};   // page id -> flag key
var FEATURE_LABEL_MAP={};  // page id -> human label
FEATURE_CATALOG.forEach(function(g){
  g.items.forEach(function(it){ FEATURE_PAGE_MAP[it.page]=it.key; FEATURE_LABEL_MAP[it.page]=it.label; });
});
var liveFeatureFlags={};        // live cache of appConfig/features, kept current site-wide
var liveFlagsUnsubGlobal=null;
var liveFlagsStarted=false;
function startLiveFeatureFlags(){
  if(liveFlagsStarted) return;
  if(!window.KSFirebase || !window.KSFirebase.subscribeFeatureFlags) return;
  liveFlagsStarted=true;
  liveFlagsUnsubGlobal=window.KSFirebase.subscribeFeatureFlags(function(flags,err){
    if(err) return;
    liveFeatureFlags=flags||{};
    if(isPageBlocked(curPage)){ go('home'); }
    else{ applyFeatureFlagUI(); }
  });
}
// Live-updates the About Me photo for every visitor as soon as the admin uploads a
// new one (siteConfig/about in Firestore) — falls back to DEFAULT_ABOUT_PHOTO until
// then, or if the admin never uploads a replacement. (added)
var aboutPhotoUnsubGlobal=null;
var aboutPhotoStarted=false;
function startLiveAboutPhoto(){
  if(aboutPhotoStarted) return;
  if(!window.KSFirebase || !window.KSFirebase.subscribeAboutPhoto) return;
  aboutPhotoStarted=true;
  aboutPhotoUnsubGlobal=window.KSFirebase.subscribeAboutPhoto(function(dataUrl,err){
    if(err) return;
    liveAboutPhoto=dataUrl||null;
    if(curPage==='home') renderHome();
  });
}
// A key counts as OFF only when explicitly stored as false — everything is
// on by default. Admins (communityIsAdmin) always see every page, so they
// can preview/undo a pause without needing to flip it back on blind.
function isPageBlocked(page){
  var key=FEATURE_PAGE_MAP[page];
  if(!key) return false;
  if(typeof communityIsAdmin==='function' && communityIsAdmin()) return false;
  return !!(liveFeatureFlags && liveFeatureFlags[key]===false);
}
function renderFeatureDisabledPage(page){
  var label=FEATURE_LABEL_MAP[page]||'This section';
  appEl.innerHTML='<section class="page-wrap">'
    +'<div class="back-row"><button class="back-btn" onclick="go(\'home\')">← Home</button></div>'
    +'<div class="admin-card" style="text-align:center;padding:44px 20px">'
      +'<div style="font-size:40px;margin-bottom:12px">🚧</div>'
      +'<h2 class="section-title" style="margin-bottom:8px">'+escapeHTML(label)+' is paused</h2>'
      +'<p style="color:var(--muted)">The site admin has temporarily turned this off. Please check back later.</p>'
    +'</div>'
  +'</section>';
}
// Dims any on-screen link/tile that points at a currently-paused page (nav bar,
// mobile menu, home tiles, games/health grids, apps list) — purely visual;
// the real block happens in go() itself, so this can't be bypassed by CSS.
function applyFeatureFlagUI(){
  document.querySelectorAll('[onclick]').forEach(function(n){
    var oc=n.getAttribute('onclick')||'';
    var m=oc.match(/go\(['"]([a-zA-Z0-9_]+)['"]\)/);
    if(!m || !FEATURE_PAGE_MAP.hasOwnProperty(m[1])) return;
    var blocked=isPageBlocked(m[1]);
    n.classList.toggle('feature-paused', blocked);
    var tag=n.querySelector('.feature-paused-tag');
    if(blocked && !tag){
      tag=document.createElement('span');
      tag.className='feature-paused-tag';
      tag.textContent='Paused';
      n.appendChild(tag);
    }else if(!blocked && tag){ tag.remove(); }
  });
}

